mapper.select:
SELECT COUNT(*)
FROM reservation
WHERE facility_id = #{facilityId}
AND reservation_date = #{reservationDate}
AND status IN (0, 1)
AND NOT (end_time <= #{startTime} OR start_time >= #{endTime})

    AND id != #{excludeId}

mapper.update:
UPDATE reservation
SET status = #{status}, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT 
FROM reservation
WHERE facility_id = #{facilityId}
AND reservation_date BETWEEN #{startDate} AND #{endDate}
AND status IN (0, 1, 2)
ORDER BY reservation_date ASC, start_time ASC
